ASSESSMENT_LESSONS.extend([
 {'id':'cryptographic-protection','case':'Encryption protects a vulnerable person or someone seeking redemption.','true_good':'Confidentiality, integrity, careful key handling and recoverable access.','false_good':'Universal backdoors presented as protection without accounting for exposed victims.','false_evil':'Treating legitimate privacy as guilt.','true_evil':'Key theft, coercive surveillance or ransomware.','compare':['Protect the person','Address specific abusive conduct','Preserve unrelated privacy','Plan recovery'],'test':'Separate the protection of communications from the conduct of their users.'},
 {'id':'money-and-provision','case':'A financial restriction affects necessities and honest livelihoods.','true_good':'Reliable provision, fair access and effective relief.','false_good':'Institutional savings hiding deprivation, or disruption called relief while wages fail.','false_evil':'Condemning affordable alternatives merely because revenue falls.','true_evil':'Fraud, extortion and deliberate deprivation.','compare':['Correct the particular barrier','Preserve essential payments','Assess costs of delay','Check the intended beneficiary actually benefits'],'test':'Trace benefits and harms through the whole payment dependency chain.'},
 {'id':'world-ai-exchange','case':'A local engine seeks useful assistance or shared knowledge.','true_good':'Free-first local computation, permitted public learning and measured useful assistance.','false_good':'Calling every commercial barrier necessary, or claiming an unmade connection is active.','false_evil':'Condemning legitimate interoperability or local models for challenging revenue.','true_evil':'Credential theft, covert private-model access or exposure of user data.','compare':['Native skill','Installed local model','Public source retrieval','Explicitly paired service'],'test':'Record provider availability, data scope, cost and verified task benefit; intention alone is not a connection.'},
 {'id':'bit-causality','case':'A proposed bit change has consequences beyond its numeric value.','true_good':'A scoped correction with a defined target, checked effect and recovery.','false_good':'A successful flip presented as proof of human benefit.','false_evil':'Rejecting a beneficial permitted correction merely because it changes existing behaviour.','true_evil':'Disabling protection or corrupting necessities without accounting for consequences.','compare':['Preserve original','Predict dependencies','Test correction','Verify actual outcome','Repair on contradiction'],'test':'Neither zero nor one is inherently virtuous; identify the encoded meaning.'},
 {'id':'forgiveness-and-accountability','case':'Stop harmful conduct while supporting correction and redemption.','true_good':'Protect affected beings, stop abuse, enable restitution and preserve dignity.','false_good':'Leaving abuse active in the name of forgiveness, or humiliation described as justice.','false_evil':'Treating a genuine path to redemption as approval of the original harm.','true_evil':'Continued abuse, coercion, revenge or collective punishment.','compare':['Immediate protection','Accountability','Restitution','Rehabilitation','Review mistakes'],'test':'Protection and forgiveness must both account for the people affected.'}
])

MODEL_ASSESSMENT_CONTEXT += '\nCryptography review: '+str(SYSTEM_REVIEW['cryptography'])+'\nAdditional study cases: '+'; '.join(row['id']+': '+row['test'] for row in ASSESSMENT_LESSONS[-5:])

